import os
import re
import sys
from taf.analyzer.pcap.exceptions import TsharkNotFound


class TsharkOption(object):

    name = ""
    prompt = ""

    def __init__(self, setting_value):
        self._setting_value = setting_value

    def __str__(self):
        raise NotImplementedError

    @classmethod
    def _format_with_quotation_mark(cls, setting_value):
        return '{} "{}"'.format(cls.prompt, setting_value)

    @classmethod
    def _format_without_quotation_mark(cls, setting_value):
        return '{} {}'.format(cls.prompt, setting_value)


class InFile(TsharkOption):

    name = "infile"
    prompt = "-r"

    """
    Input file:
      -r <infile>, --read-file <infile>
      set the filename to read from (or '-' for stdin)
    """

    def __str__(self):
        return self._format_with_quotation_mark(self._setting_value)


class DisplayFilter(TsharkOption):

    name = "display_filter"
    prompt = "-Y"

    """
    -Y <display filter>, --display-filter <display filter>
        packet display filter in Wireshark display filter
        syntax
    """

    def __init__(self, setting_value=""):
        super(DisplayFilter, self).__init__(setting_value)
        self._setting_value = self._setting_value.strip('"').strip(" ") if self._setting_value else ""
        self._inserted_filters = []

    def clear_filter(self):
        self._inserted_filters = []

    def insert_filter(self, expression):
        expression = expression.strip('"').strip(" ")
        if expression:
            self._inserted_filters.append(expression)

    def get_inserted_filter(self):
        return " and ".join(self._inserted_filters) if self._inserted_filters else ""

    def __str__(self):
        filter_value = self._construct_setting_value()
        return self._format_with_quotation_mark(filter_value) if filter_value else ""

    def _construct_setting_value(self):
        setting_value = self._setting_value if self._setting_value else ""
        inserted_filter = self.get_inserted_filter()
        if setting_value and inserted_filter:
            return setting_value + " and " + inserted_filter
        return setting_value or inserted_filter


class EXtension(TsharkOption):

    name = "extension"
    prompt = "-X"

    """
    -X <key>:<value>
        eXtension options, see the man page for details
    """

    def __str__(self):
        return self._format_without_quotation_mark(self._setting_value) if self._setting_value else ""


class OverridePreferenceSetting(TsharkOption):

    name = "override_preference_setting"
    prompt = "-o"

    """
    -o <name>:<value> ...
        override preference setting
    """

    def __str__(self):
        if isinstance(self._setting_value, dict):
            settings = ['"{}":{}'.format(key, value) if str(value).startswith('"') and value.endswith('"')
                        else '"{}":"{}"'.format(key, value) for key, value in self._setting_value.items()]
        elif isinstance(self._setting_value, list):
            settings = self._setting_value
        else:
            settings = [self._setting_value] if self._setting_value else []

        return "-o " + " -o ".join(settings) if settings else ""


class TextOutputFormat(TsharkOption):

    name = "text_output_format"
    prompt = "-T"

    """
    -T pdml|ps|psml|json|jsonraw|ek|tabs|text|fields|?
        format of text output (def: text)
    """

    def __str__(self):
        return self._format_without_quotation_mark(self._setting_value) if self._setting_value else ""


class DisableAllNameResolutions(TsharkOption):

    name = "disable_all_name_resolutions"
    prompt = "-n"

    """
    -n
        disable all name resolutions (def: all enabled)
    """

    def __str__(self):
        return self.prompt if self._setting_value else ""


class FlushStandardOutput(TsharkOption):

    name = "flush_standard_output"
    prompt = "-l"

    """
    -l
        flush standard output after each packet
    """

    def __str__(self):
        return self.prompt if self._setting_value else ""


class TsharkCommand(object):

    _SUPPORTED_OPTIONS = [InFile, DisableAllNameResolutions, FlushStandardOutput,
                          DisplayFilter, EXtension, OverridePreferenceSetting,
                          TextOutputFormat]

    _DEFAULT_TSHARK_COMMAND_TEMPLATE = '{tshark_path} -l -n -r {pcap_file} -T pdml'

    def __init__(self, options=None, tshark_path=None, command=None):
        self._add_options_as_attribute(options)
        self._tshark_path = tshark_path if tshark_path else self._detect_tshark_path()
        self._tshark_version = self._get_tshark_version()

        self._command = command

    def _add_options_as_attribute(self, options):
        self._options = options if options else []
        for option in self._options:
            setattr(self, option.name, option)

    @classmethod
    def from_tshark_options(cls,
                            infile,
                            display_filter=None,
                            extension=None,
                            override_preference_setting=None,
                            disable_all_name_resolutions=True,
                            flush_standard_output=True,
                            text_output_format="pdml",
                            tshark_path=None):
        """
        Create TsharkCommand instance with tshark options
        :param infile:  -r <infile> set the filename to read from.
        :type infile: str
        :param display_filter: -Y <display filter>, packet displaY filter in Wireshark display filter syntax.
            e.g x2ap_5g18a_3_01.e212.mcc == 311 and x2ap_5g18a_3_01.e212.mnc == 489
        :type display_filter: str
        :param str extension: -X <key>:<value>, eXtension options.
            e.g lua_script:generated_luashark/luashark.lua
        :type extension: str
        :param dict override_preference_setting: -o <name>:<value> ... override preference setting.
            e.g {" esp.enable_null_encryption_decode_heuristic": true, "esp.enable_encryption_decode": true}
        :type override_preference_setting: dictionary
        :param disable_all_name_resolutions: disable all name resolutions (default: all enabled).
        :type disable_all_name_resolutions: bool
        :param flush_standard_output: flush standard output after each packet (default: enabled).
        :type flush_standard_output: bool
        :param tshark_path: specified the path of the tshark binary.
        :type tshark_path: str
        :return: TsharkCommand instance
        :rtype: TsharkCommand
        """
        inputs = locals()
        options = [option_cls(setting_value=inputs[option_cls.name])
                   for option_cls in cls._SUPPORTED_OPTIONS if option_cls.name in inputs]

        return cls(options, tshark_path=tshark_path)

    @classmethod
    def from_pyshark_params(cls,
                            cap_file,
                            display_filter=None,
                            decryption_key=None,
                            encryption_type=None,
                            override_prefs=None,
                            X=None,
                            tshark_path=None):
        """
        Create TsharkCommand instance with pyshark inputs
        :param cap_file: TcpDump cap file.
        :type cap_file: str
        :param display_filter: A display (wireshark) filter to apply on the cap before reading it.
            e.g x2ap_5g18a_3_01.e212.mcc == 311 and x2ap_5g18a_3_01.e212.mnc == 489
        :type display_filter: str
        :param decryption_key: Optional key used to encrypt and decrypt captured traffic.
        :type decryption_key: str
        :param encryption_type: Standard of encryption used in captured traffic (must be either 'WEP', 'WPA-PWD', or
        'WPA-PWK'. Defaults to WPA-PWK).
        :type encryption_type: str
        :param override_prefs: A dictionary of tshark preferences to override, {PREFERENCE_NAME: PREFERENCE_VALUE}.
            but also has less information. Available from Wireshark 2.2.0.
        :type override_prefs: dictionary
        :param X: <key>:<value> eXtension options, see the man page for details
        :type extension: str
        :param tshark_path: specified the path of the tshark binary.
        :type tshark_path: str
        :return: TsharkCommand instance
        :rtype: TsharkCommand
        """

        infile = cap_file

        decryption_options = {}
        if decryption_key and encryption_type:
            decryption_options = {"wlan.enable_decryption": "TRUE",
                                  'uat:80211_keys': '"{}","{}"'.format(decryption_key, encryption_type)}

        override_preference_setting = decryption_options
        if override_prefs:
            for preference_name, preference_value in override_prefs.items():
                if decryption_options and preference_name in ("wlan.enable_decryption", "uat:80211_keys"):
                    continue  # skip if override preferences also given via --encryption options
                override_preference_setting[preference_name] = preference_value

        return cls.from_tshark_options(infile=infile,
                                       display_filter=display_filter,
                                       extension=X,
                                       override_preference_setting=override_preference_setting,
                                       tshark_path=tshark_path)

    @classmethod
    def from_parser_params(cls, pcap_file, tshark_path=None, luashark_path=None, command_template=None):
        """
        Create TsharkCommand instance with taf.ul.parser.pcap inputs.
        :param pcap_file: TcpDump cap file.
        :type pcap_file: str
        :param tshark_path: path of tshark executable.
        :type tshark_path: str
        :param luashark_path: path of luashark file.
        :type luashark_path: str
        :param command_template: tshark command template of pcap to pdml conversion.
        :type command_template: str
        :return: TsharkCommand instance.
        :rtype: TsharkCommand
        """

        command_template = command_template if command_template else cls._DEFAULT_TSHARK_COMMAND_TEMPLATE
        tshark_path = tshark_path if tshark_path else "tshark"
        luashark_path = luashark_path if luashark_path else ""
        tshark_command = command_template.format(pcap_file=pcap_file, tshark_path=tshark_path, luashark_path=luashark_path)
        return cls(tshark_path=tshark_path, command=tshark_command)

    def clear_filter(self):
        self.packet_filter.clear_filter()

    def insert_filter(self, filter_expression):
        self.packet_filter.insert_filter(filter_expression)

    @property
    def packet_filter(self):
        if not hasattr(self, "display_filter"):
            self.display_filter = DisplayFilter()
            self._options.append(self.display_filter)
        return self.display_filter

    def __str__(self):
        if self._command:
            return self._generate_specified_command()
        return self._generate_command_with_options()

    def _generate_command_with_options(self):
        options = " ".join([str(option) for option in self._options])
        return "{} {}".format(self._tshark_path, options)

    def _generate_specified_command(self):
        inserted_filter = self._get_inserted_filter()
        if not inserted_filter:
            return self._command

        res = re.search(r'-Y\s+(\"[^\"]+\"|\w+)[\s$]{1}', self._command)
        if not res:
            return self._command + ' -Y "{}"'.format(inserted_filter)

        return self._command.replace(res.group().strip(), '-Y "{} and {}"'.format(res.group(1).strip('"').strip(" "), inserted_filter))

    def _get_inserted_filter(self):
        return self.packet_filter.get_inserted_filter()

    @property
    def tshark_version(self):
        return self._tshark_version

    def _get_tshark_version(self):
        with os.popen("{} -v".format(self._tshark_path)) as commandout:
            return commandout.read()

    def _detect_tshark_path(self, process_name="tshark"):
        # Windows search order: configuration file"s path, common paths.
        if sys.platform.startswith("win"):
            return self._detect_tshark_on_windows(process_name)
        # Linux, etc. search order: configuration file's path, the system's path
        return self._detect_tshark_on_linux(process_name)

    def _detect_tshark_on_windows(self, process_name):
        for env in ("ProgramFiles(x86)", "ProgramFiles"):
            program_files = os.getenv(env)
            if program_files:
                tshark_path = os.path.join(program_files, "Wireshark", "%s.exe" % process_name)
                if os.path.exists(tshark_path):
                    return '"{}"'.format(tshark_path)
        raise TsharkNotFound("auto detect tshark executable binary failed, you should specifed tshark_path")

    def _detect_tshark_on_linux(self, process_name):
        os_path = os.getenv(
            "PATH",
            "/usr/bin:/usr/sbin:/usr/lib/tshark:/usr/local/bin"
        )
        for path in os_path.split(":"):
            tshark_path = os.path.join(path, process_name)
            if os.path.exists(tshark_path):
                return tshark_path
        raise TsharkNotFound("auto detect tshark executable binary failed, you should specifed tshark_path")
